/** The site's name, the watch page and the player a card swaps in on play. */
export const videoSite = (v: Video) => (v.site === "bilibili" ? "Bilibili" : "YouTube");
export const videoUrl = (v: Video) =>
  v.site === "bilibili" ? `https://www.bilibili.com/video/${v.id}/` : `https://www.youtube.com/watch?v=${v.id}`;
export const videoEmbed = (v: Video) =>
  v.site === "bilibili" ? `https://player.bilibili.com/player.html?bvid=${v.id}` : `https://www.youtube-nocookie.com/embed/${v.id}`;

